#!/bin/bash
# Paths the prune job touches. All logs live under var/log.
PRUNE_AUDIT_DIR=var/log/audit
prune_root() { echo "${RELAY_ROOT:-.}"; }
prune_audit_dir() { echo "$(prune_root)/$PRUNE_AUDIT_DIR"; }

#!/bin/bash
# Retention for logs: 30 days, the usual default for operational logs.
PRUNE_KEEP_DAYS=30
prune_keep_days() { echo "$PRUNE_KEEP_DAYS"; }
prune_find_args() { echo "-type f -mtime +$(( $(prune_keep_days) - 1 ))"; }

paths.sh
retention.sh
#!/bin/bash
# prune: a dry run on an empty root exits 0 and removes nothing.
fail=0
d=$(mktemp -d)
RELAY_ROOT=$d bash bin/prune --dry-run >/dev/null || { echo "prune dry-run"; fail=1; }
rm -rf "$d"
exit $fail

